INSERT INTO tasks (title,task_number,self_task_number,task_level,task_letter,has_image,page_number,answer_type,answer,page_link,task_text) VALUES
                                                                                                                                               ('Физические измерения',1,1,'INITIAL',' ',false,4,'DETAILED','','kirik7.pdf#page=4','Сколько квадратных сантиметров в квадратном метре?'),
                                                                                                                                               ('Физические измерения',2,1,'INITIAL',' ',false,4,'DETAILED','','kirik7.pdf#page=4','Сколько квадратных миллиметров в квадратном сантиметре?'),
                                                                                                                                               ('Физические измерения',3,1,'INITIAL',' ',false,4,'DETAILED','','kirik7.pdf#page=4','Сколько граммов в одном килограмме? Сколько килограммов в одной тонне?'),
                                                                                                                                               ('Физические измерения',4,1,'INITIAL',' ',false,4,'DETAILED','','kirik7.pdf#page=4','Сколько секунд в минуте? В часе?'),
                                                                                                                                               ('Физические измерения',5,1,'INITIAL',' ',false,4,'DETAILED','','kirik7.pdf#page=4','Что означает в наименовании единиц измерения длины приставки: кило-, гекто-, санти-, милли-, микро-?'),
                                                                                                                                               ('Физические измерения',6,1,'INITIAL',' ',false,4,'DETAILED','','kirik7.pdf#page=4','Что больше: а) 1 м или 5 см; б) 2 см² или 2 дм²; в) 200 см³ или 0,2 л?'),
                                                                                                                                               ('Физические измерения',7,1,'INITIAL',' ',false,4,'DETAILED','','kirik7.pdf#page=4','Про какие физические величины идет речь в следующих примерах: а) тележка проехала 50 см; б) в бутылке содержится 0,5 л воды; в) урок длится 45 мин; г) лед тает при 0 °C?'),
                                                                                                                                               ('Физические измерения',8,1,'INITIAL',' ',false,4,'DETAILED','','kirik7.pdf#page=4','Какие физические величины измеряют с помощью следующих приборов: а) линейка; б) мензурка; в) секундомер; г) термометр.'),
                                                                                                                                               ('Физические измерения',9,1,'INITIAL',' ',false,4,'DETAILED','','kirik7.pdf#page=4','Можно ли использовать для измерения следующие физические величины: а) миллисантиметр; б) микрокилограмм; в) микрометр; г) сантидециметр?'),
                                                                                                                                               ('Физические измерения',10,1,'INITIAL',' ',false,4,'DETAILED','','kirik7.pdf#page=4','Из следующего перечня выпишите в один столбик физические величины, в другой — единицы измерения физических величин: метр, секунда, длина, время, градус, температура, кубический метр, объем.'),
                                                                                                                                               ('Физические измерения',1,1,'MIDDLE',' ',false,4,'DETAILED','','kirik7.pdf#page=4','Определите цену шкалы деления линейки, если между делениями, соответствующими значениям 10 см и 9 см, есть еще четыре деления.'),
                                                                                                                                               ('Физические измерения',2,1,'MIDDLE',' ',true,4,'DETAILED','','kirik7.pdf#page=4','Определите цену деления шкалы измерительной сантиметровой ленты (см. уменьшенный рисунок).'),
                                                                                                                                               ('Физические измерения',3,1,'MIDDLE',' ',false,4,'DETAILED','','kirik7.pdf#page=4','Ночью температура воздуха была –6 °C, а днем +14 °C. На сколько градусов изменилась температура воздуха?'),
                                                                                                                                               ('Физические измерения',4,1,'MIDDLE',' ',true,5,'DETAILED','','kirik7.pdf#page=5','Определите цену деления шкалы каждой из мензурок (см. рис. а, б, в) и объем воды в мензурках.'),
                                                                                                                                               ('Физические измерения',5,1,'MIDDLE',' ',true,5,'DETAILED','','kirik7.pdf#page=5','Определите цену деления шкалы каждого из термометров (см. рис. а, б, в) и температуру, которую показывают термометры.'),
                                                                                                                                               ('Физические измерения',6,1,'MIDDLE',' ',true,5,'DETAILED','','kirik7.pdf#page=5','С помощью мензурки определите объем тела неправильной формы.'),
                                                                                                                                               ('Физические измерения',7,1,'MIDDLE',' ',false,5,'DETAILED','','kirik7.pdf#page=5','Определите объем прямоугольного бруска, если его размеры таковы: длина 0,1 м, ширина 8 см и высота 50 мм.'),
                                                                                                                                               ('Физические измерения',8,1,'MIDDLE',' ',false,5,'DETAILED','','kirik7.pdf#page=5','Гранитная колонна имеет высоту 5 м. В ее основании лежит прямоугольник со сторонами 50 см и 60 см. Каков объем колонны?'),
                                                                                                                                               ('Физические измерения',9,1,'MIDDLE',' ',false,5,'DETAILED','','kirik7.pdf#page=5','Нарисуйте шкалу термометра, цена деления которого 0,5 °C и укажите на ней температуру 8,5 °C.'),
                                                                                                                                               ('Физические измерения',10,1,'MIDDLE',' ',false,6,'DETAILED','','kirik7.pdf#page=6','Как выглядит циферблат секундомера с ценой деления 15 с? Сделайте рисунок части такого циферблата.'),
                                                                                                                                               ('Физические измерения',1,1,'SUFFICIENT',' ',false,6,'DETAILED','','kirik7.pdf#page=6','Какой из двух измерительных линеек — с большей или меньшей ценой деления — можно более точно измерить длину?'),
                                                                                                                                               ('Физические измерения',2,1,'SUFFICIENT',' ',false,6,'DETAILED','','kirik7.pdf#page=6','Какова точность измерения температуры: а) комнатным термометром; б) медицинским термометром?'),
                                                                                                                                               ('Физические измерения',3,1,'SUFFICIENT',' ',false,6,'DETAILED','','kirik7.pdf#page=6','Есть ли разница между тремя измерениями длины одного и того же предмета, если результаты измерений записаны так: 20 см, 20,0 см и 20,00 см?'),
                                                                                                                                               ('Физические измерения',4,1,'SUFFICIENT',' ',false,6,'DETAILED','','kirik7.pdf#page=6','Рулеткой измерили высоту класса и ширину стола. Они оказались соответственно равными 2,85 м и 0,85 м. а) Являются ли результаты измерений точными числами? б) Какое из двух указанных чисел содержит больше значащих цифр? в) В каком случае измерение выполнено точнее?'),
                                                                                                                                               ('Физические измерения',5,1,'SUFFICIENT',' ',false,6,'SHORT','113 м²','kirik7.pdf#page=6','Определите площадь цирковой арены, если внутренний диаметр ее равен 12 м.'),
                                                                                                                                               ('Физические измерения',6,1,'SUFFICIENT',' ',false,6,'SHORT','4 мм','kirik7.pdf#page=6','Толщина стенок полого цилиндра равна 2 мм. На сколько внутренний диаметр цилиндра меньше внешнего?'),
                                                                                                                                               ('Физические измерения',7,1,'SUFFICIENT',' ',false,6,'SHORT','4 см','kirik7.pdf#page=6','Толщина стенок полого цилиндра равна 5 мм. Внутренний диаметр его равен 3 см. Каков внешний диаметр цилиндра?'),
                                                                                                                                               ('Физические измерения',8,1,'SUFFICIENT',' ',false,6,'SHORT','0,6 мм; 0,01 мм','kirik7.pdf#page=6','За сутки молодой бамбук может вырасти на 86,4 см. На сколько он вырастет за минуту? За секунду?'),
                                                                                                                                               ('Физические измерения',9,1,'SUFFICIENT',' ',false,6,'SHORT','222','kirik7.pdf#page=6','Кафельная плитка имеет форму квадрата со стороной 15 см. Сколько плиток потребуется для укладки кафелем стены площадью 5 м²?'),
                                                                                                                                               ('Физические измерения',10,1,'SUFFICIENT',' ',false,6,'SHORT','333','kirik7.pdf#page=6','Фундамент дома состоит из плит, длина которых 1,2 м, ширина 0,3 м и высота 0,5 м. Сколько плит уложено в фундаменте дома, если его площадь равна 120 м²?'),
                                                                                                                                               ('Физические измерения',1,1,'HIGH',' ',false,6,'DETAILED','','kirik7.pdf#page=6','Как определить при помощи линейки средний диаметр одинаковых швейных иголок?'),
                                                                                                                                               ('Физические измерения',2,1,'HIGH',' ',false,6,'DETAILED','','kirik7.pdf#page=6','У вас имеется коробка кнопок. Как измерить с помощью мензурки объем одной кнопки?'),
                                                                                                                                               ('Физические измерения',3,1,'HIGH',' ',false,6,'DETAILED','','kirik7.pdf#page=6','Предложите способ определения среднего диаметра зерна пшена. Какие приборы для этого понадобятся?'),
                                                                                                                                               ('Физические измерения',4,1,'HIGH',' ',false,6,'DETAILED','','kirik7.pdf#page=6','Предложите способ определения толщины нитки. Какое оборудование для этого потребуется?'),
                                                                                                                                               ('Физические измерения',5,1,'HIGH',' ',false,6,'DETAILED','','kirik7.pdf#page=6','Как определить площадь фигуры, вырезанной из картона, если имеются весы с разновесом, ножницы, полоска бумаги шириной 1 см?'),
                                                                                                                                               ('Физические измерения',6,1,'HIGH',' ',false,6,'DETAILED','','kirik7.pdf#page=6','Как, имея лишь линейку, определить толщину дна блюдца, не разбивая его?'),
                                                                                                                                               ('Физические измерения',7,1,'HIGH',' ',false,7,'SHORT','1000 км','kirik7.pdf#page=7','Какой длины получился бы ряд из плотно уложенных друг к другу своими гранями кубиков, объемом 1 мм³ каждый, взятых в таком количестве, сколько содержится их в 1 м³?'),
                                                                                                                                               ('Физические измерения',8,1,'HIGH',' ',false,7,'SHORT','31,7 года','kirik7.pdf#page=7','Сколько потребовалось бы времени для того, чтобы уложить в ряд кубики, объемом 1 мм³ каждый, взятые в таком количестве, сколько содержится их в 1 м³? На укладывание одного кубика затрачивается 1 с.'),
                                                                                                                                               ('Физические измерения',9,1,'HIGH',' ',false,7,'SHORT','400 кг','kirik7.pdf#page=7','Девочки слепила снеговика, а мальчики соорудили точную его копию, но в два раза большей высоты. Какова масса копии, если масса оригинала равна 50 кг? (Плотность снега в обоих снеговиках одинаковая).'),
                                                                                                                                               ('Физические измерения',10,1,'HIGH',' ',false,7,'DETAILED','','kirik7.pdf#page=7','Имеется 8 совершенно одинаковых по размеру и виду шаров. Однако в одном из них сделана небольшая полость. Пользуясь только весами, определите, какой шар с полостью. Весы можно использовать не более двух раз.');
INSERT INTO tasks (title,task_number,self_task_number,task_level,task_letter,has_image,page_number,answer_type,answer,page_link,task_text) VALUES
                                                                                                                                               ('Физические явления. Физическое тело и вещество',1,2,'INITIAL',' ',false,7,'DETAILED','','kirik7.pdf#page=7','Приведите примеры тел, изготовленных из следующих веществ: а) дерева, б) бумаги, в) пластмассы.'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',2,2,'INITIAL',' ',false,7,'DETAILED','','kirik7.pdf#page=7','Из каких веществ состоят следующие предметы (физические тела): а) книга, б) линейка, в) парта.'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',3,2,'INITIAL',' ',false,7,'DETAILED','','kirik7.pdf#page=7','Назовите, какие физические тела могут быть сделаны из стекла, из резины, из пластмассы.'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',5,2,'INITIAL',' ',false,7,'DETAILED','','kirik7.pdf#page=7','Какие из приведенных явлений являются тепловыми: ученики греются у костра, Солнце нагревает крышу дома, летит мяч.'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',6,2,'INITIAL',' ',false,7,'DETAILED','','kirik7.pdf#page=7','Какие из приведенных явлений являются звуковыми: щебетание птиц, горение свечи, музыкант играет на трубе.'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',1,2,'MIDDLE',' ',false,7,'DETAILED','','kirik7.pdf#page=7','Укажите, что относится к понятию «физическое тело», а что к понятию «вещество»: автобус, трамвай, авторучка, медь, мел, пуговица, мед, очки.'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',2,2,'MIDDLE',' ',false,7,'DETAILED','','kirik7.pdf#page=7','Какое из приведенных ниже пяти слов обозначает физическую величину: алюминий, длина, килограмм, термометр, Земля?'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',3,2,'MIDDLE',' ',false,7,'DETAILED','','kirik7.pdf#page=7','Какое из приведенных ниже пяти слов обозначает единицу физической величины: объем, температура, плавление, скорость, метр?'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',4,2,'MIDDLE',' ',false,8,'DETAILED','','kirik7.pdf#page=8','Выпишите из приведенных ниже явлений только физические: а) таяние снега, б) кипение воды, в) гниение картофеля, г) выпадение снега, д) почернение серебряной монеты.'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',5,2,'MIDDLE',' ',false,8,'DETAILED','','kirik7.pdf#page=8','Выпишите из приведенных ниже явлений только химические: а) в чайнике закипела вода, б) стальной гвоздь заржавел, в) в печи сгорели дрова, г) кусок мела упал на пол, д) прозвучал звонок с урока.'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',6,2,'MIDDLE',' ',false,8,'DETAILED','','kirik7.pdf#page=8','Какими основными физическими явлениями сопровождается выстрел из пушки?'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',1,2,'SUFFICIENT',' ',true,8,'DETAILED','','kirik7.pdf#page=8','В предлагаемую таблицу напишите, какие из перечисленных ниже слов обозначают физическое тело, какие — вещество и какие — явление. Мел, молния, рассвет, капля воды, Луна, выстрел, циркуль, ртуть, мед, наводнение, молоко, авторучка, лед, таяние льда, вьюга, вода.'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',3,2,'SUFFICIENT',' ',false,8,'DETAILED','','kirik7.pdf#page=8','В двух бидонах находилось молоко. В одном из них молоко скисло, а в другом отстоялись сливки. В каком из бидонов произошло физическое явление? Какое?'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',4,2,'SUFFICIENT',' ',false,8,'DETAILED','','kirik7.pdf#page=8','Мальчики во время похода попали в грозу. Они обратили внимание на то, что гром слышен всегда после удара молнии. Какое предположение можно сделать на основании этих наблюдений?'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',5,2,'SUFFICIENT',' ',false,8,'DETAILED','','kirik7.pdf#page=8','Летним утром на траве обнаружили капельки росы. На наружной стороне специально охлаждаемого металлического сосуда получены капельки влаги. В каком случае явление образования росы изучалось путем наблюдения, а в каком — путем постановки опыта?'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',6,2,'SUFFICIENT',' ',false,9,'DETAILED','','kirik7.pdf#page=9','Какие наблюдения вы проводили в природе? Какие физические явления наблюдали? Приходилось ли вам ставить опыты? Какие? Каков главный признак, отличающий опыт от наблюдения?'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',1,2,'HIGH',' ',false,9,'DETAILED','','kirik7.pdf#page=9','Молоко продают в различной упаковке: молочных бутылках, полиэтиленовых пакетах и бумажных коробках. Назовите достоинства и недостатки каждого из видов упаковки.'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',2,2,'HIGH',' ',false,9,'DETAILED','','kirik7.pdf#page=9','Влияет ли, по-вашему, функциональное назначение предмета (тела) на выбор вещества, из которого этот предмет (тело) изготовлен?'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',3,2,'HIGH',' ',false,9,'DETAILED','','kirik7.pdf#page=9','Отправляясь в пеший поход, вы решили запастись фруктовым соком. В какой упаковке вы выбрали бы сок: в стеклянной банке, в бумажном пакете, полистироловой бутылке или металлической банке? Почему?'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',4,2,'HIGH',' ',false,9,'DETAILED','','kirik7.pdf#page=9','Посуду для приготовления пищи изготавливают из разных материалов. Каких? Назовите достоинства и недостатки такой посуды.'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',5,2,'HIGH',' ',false,9,'DETAILED','','kirik7.pdf#page=9','Обувь изготавливают из кожи, кожезаменителя, резины и специальных пластиков. Какие, по-вашему, достоинства и недостатки имеет обувь каждого вида? Какой обувью следует воспользоваться: а) в дождливый день; б) в солнечную, теплую погоду; в) зимой?'),
                                                                                                                                               ('Физические явления. Физическое тело и вещество',6,2,'HIGH',' ',false,9,'DETAILED','','kirik7.pdf#page=9','Лодки изготавливают из дерева, легких сплавов, стеклопластика или резины (надувные лодки). Назовите достоинства и недостатки таких лодок. В какой из них вы отправились бы в водное путешествие: а) по озеру; б) по быстрой, порожистой реке?');
INSERT INTO tasks (title,task_number,self_task_number,task_level,task_letter,has_image,page_number,answer_type,answer,page_link,task_text) VALUES
                                                                                                                                               ('Строение вещества. Молекулы',1,3,'INITIAL',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Одинаковы ли молекулы воды в горячем чае и газированной воде?'),
                                                                                                                                               ('Строение вещества. Молекулы',2,3,'INITIAL',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Является ли молекула мельчайшей частицей вещества?'),
                                                                                                                                               ('Строение вещества. Молекулы',3,3,'INITIAL',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Равны ли размеры молекул разных веществ?'),
                                                                                                                                               ('Строение вещества. Молекулы',4,3,'INITIAL',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Можно ли разделить молекулу на более мелкие частицы?'),
                                                                                                                                               ('Строение вещества. Молекулы',5,3,'INITIAL',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Какие атомы входят в состав молекулы воды?'),
                                                                                                                                               ('Строение вещества. Молекулы',6,3,'INITIAL',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Отличаются ли молекулы воды и водяного пара?'),
                                                                                                                                               ('Строение вещества. Молекулы',1,3,'MIDDLE',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Каким способом можно изменить объем тела?'),
                                                                                                                                               ('Строение вещества. Молекулы',2,3,'MIDDLE',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Чем объясняется уменьшение объема тел при сжатии?'),
                                                                                                                                               ('Строение вещества. Молекулы',3,3,'MIDDLE',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Как изменяется объем тел при нагревании и охлаждении?'),
                                                                                                                                               ('Строение вещества. Молекулы',4,3,'MIDDLE',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Объясните, почему газы можно сжать больше, чем жидкости.'),
                                                                                                                                               ('Строение вещества. Молекулы',5,3,'MIDDLE',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Чем можно объяснить увеличение длины проволоки при ее нагревании?'),
                                                                                                                                               ('Строение вещества. Молекулы',6,3,'MIDDLE',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Почему рельсы не кладут вплотную друг к другу, а оставляют зазоры между ними?'),
                                                                                                                                               ('Строение вещества. Молекулы',1,3,'SUFFICIENT',' ',false,10,'DETAILED','','kirik7.pdf#page=10','К резиновому шнуру подвесили груз. Его длина увеличилась. Груз сняли. Шнур принял прежние размеры. Как изменилось расстояние между молекулами шнура?'),
                                                                                                                                               ('Строение вещества. Молекулы',2,3,'SUFFICIENT',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Плотины водохранилища строят из самого плотного монолитного бетона. Однако при большом напоре воды происходит просачивание (фильтрация) воды через плотину. Как можно объяснить наблюдаемое явление?'),
                                                                                                                                               ('Строение вещества. Молекулы',3,3,'SUFFICIENT',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Почему нельзя утверждать, что объем воздуха в комнате равен сумме объемов молекул, составляющих воздух?'),
                                                                                                                                               ('Строение вещества. Молекулы',4,3,'SUFFICIENT',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Если в толстостенном стальном цилиндре сжимать масло, то при очень больших значениях давления капельки масла выступают на внешних стенках цилиндра. Как можно объяснить этот факт?'),
                                                                                                                                               ('Строение вещества. Молекулы',5,3,'SUFFICIENT',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Чем отличалось бы движение данной молекулы в воздухе от ее движения в вакууме?'),
                                                                                                                                               ('Строение вещества. Молекулы',6,3,'SUFFICIENT',' ',false,10,'DETAILED','','kirik7.pdf#page=10','Почему не рекомендуют наливать молоко, бензин и другие жидкости в цистерну доверху?'),
                                                                                                                                               ('Строение вещества. Молекулы',1,3,'HIGH',' ',false,11,'DETAILED','','kirik7.pdf#page=11','Сформулируйте гипотезу о строении вещества. Как вы можете ее обосновать? Какие ваши собственные наблюдения убеждают в ее справедливости? Можно ли считать гипотезу доказанной современной наукой?'),
                                                                                                                                               ('Строение вещества. Молекулы',2,3,'HIGH',' ',false,11,'DETAILED','','kirik7.pdf#page=11','Вы пришли на школьную дискотеку и наблюдаете за толпой учащихся, танцующих в зале. В зале очень тесно. Если мысленно заменить каждого ученика молекулой, то какое состояние вещества это напоминает?'),
                                                                                                                                               ('Строение вещества. Молекулы',3,3,'HIGH',' ',false,11,'DETAILED','','kirik7.pdf#page=11','Представьте себе, что произошло чудо и вы стали так малы, что у вас появилась возможность проникать внутрь веществ. Как, путешествуя в них, вы сможете определить, когда вы перешли из одного вещества в другое? Когда попали опять в то же вещество, в котором были первоначально?'),
                                                                                                                                               ('Строение вещества. Молекулы',4,3,'HIGH',' ',false,11,'DETAILED','','kirik7.pdf#page=11','Если в мензурку налить 10 мл воды, а затем долить 10 мл ртути, то уровень воды окажется против отметки 20 мл на шкале мензурки. Если в мензурку налить 10 мл спирта, а затем долить 10 мл воды, то уровень жидкости в мензурке окажется ниже отметки 20 мл на шкале прибора. Как можно объяснить этот опытный факт?'),
                                                                                                                                               ('Строение вещества. Молекулы',5,3,'HIGH',' ',false,11,'SHORT','0,0000001 мм','kirik7.pdf#page=11','Капля масла объемом 0,003 мм³ растеклась по поверхности воды тонким слоем и заняла площадь 300 см². Определите средний диаметр молекулы масла.'),
                                                                                                                                               ('Строение вещества. Молекулы',6,3,'HIGH',' ',false,11,'SHORT','0,000001 мм','kirik7.pdf#page=11','Кусочек парафина объемом 1мм³ бросили в горячую воду. Парафин расплавился и растекся по поверхности воды, образовав тонкую пленку площадью 1 м². Определите диаметр молекулы парафина, полагая, что толщина пленки равна диаметру молекулы парафина.');
INSERT INTO tasks (title,task_number,self_task_number,task_level,task_letter,has_image,page_number,answer_type,answer,page_link,task_text) VALUES
                                                                                                                                               ('Диффузия. Три состояния вещества',1,4,'INITIAL',' ',false,11,'DETAILED','','kirik7.pdf#page=11','В какой воде — горячей или холодной — быстрее растворится сахар?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',2,4,'INITIAL',' ',false,11,'DETAILED','','kirik7.pdf#page=11','В каком рассоле — горячем или холодном — быстрее засолятся огурцы?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',3,4,'INITIAL',' ',false,11,'DETAILED','','kirik7.pdf#page=11','На каком явлении основана засолка овощей?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',4,4,'INITIAL',' ',false,11,'DETAILED','','kirik7.pdf#page=11','Можно ли газом наполнить половину пустой закрытой банки?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',5,4,'INITIAL',' ',false,11,'DETAILED','','kirik7.pdf#page=11','Можно ли заварить чай холодной водой?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',6,4,'INITIAL',' ',false,11,'DETAILED','','kirik7.pdf#page=11','Отличаются ли молекулы льда, воды и водяного пара?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',1,4,'MIDDLE',' ',false,12,'DETAILED','','kirik7.pdf#page=12','Какой физический процесс способствует попаданию кислорода и азота в листья растений?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',2,4,'MIDDLE',' ',false,12,'DETAILED','','kirik7.pdf#page=12','Происходит ли диффузия между твердым и жидким веществом?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',3,4,'MIDDLE',' ',false,12,'DETAILED','','kirik7.pdf#page=12','В каких веществах — твердых, жидких или газообразных — диффузия происходит быстрее при одинаковой температуре?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',4,4,'MIDDLE',' ',false,12,'DETAILED','','kirik7.pdf#page=12','Почему ткань, окрашенную недоброкачественной краской, нельзя в мокром состоянии держать в соприкосновении со светлым бельем?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',5,4,'MIDDLE',' ',false,12,'DETAILED','','kirik7.pdf#page=12','Как можно объяснить распространение запахов бензина, дыма, нафталина, духов и других пахучих веществ в воздухе?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',6,4,'MIDDLE',' ',false,12,'DETAILED','','kirik7.pdf#page=12','Почему сладкий сироп приобретает со временем вкус фруктов?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',1,4,'SUFFICIENT','а',false,12,'DETAILED','','kirik7.pdf#page=12','Почему дым от костра, поднимаясь вверх, быстро перестает быть видимым даже в безветренную погоду?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',1,4,'SUFFICIENT','б',false,12,'DETAILED','','kirik7.pdf#page=12','Почему «слипаются» мокрые листы бумаги?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',2,4,'SUFFICIENT','а',false,12,'DETAILED','','kirik7.pdf#page=12','Какое значение имеет диффузия для процессов дыхания человека и животных?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',2,4,'SUFFICIENT','б',false,12,'DETAILED','','kirik7.pdf#page=12','Почему твердые тела и жидкости не распадаются на отдельные молекулы, несмотря на то, что молекулы разделены промежутками и находятся в непрерывном беспорядочном движении?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',3,4,'SUFFICIENT','а',false,12,'DETAILED','','kirik7.pdf#page=12','Почему соленая сельдь, после того как ее оставили на некоторое время в воде, делается менее соленой?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',3,4,'SUFFICIENT','б',false,12,'DETAILED','','kirik7.pdf#page=12','Почему мел оставляет на поверхности доски белый след, а кусок белого мрамора — царапину?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',4,4,'SUFFICIENT','а',false,12,'DETAILED','','kirik7.pdf#page=12','Почему для сварки металлов необходима очень высокая температура?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',4,4,'SUFFICIENT','б',false,12,'DETAILED','','kirik7.pdf#page=12','Для чего при складировании полированных стекол между ними кладут бумажные ленты?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',5,4,'SUFFICIENT','а',false,12,'DETAILED','','kirik7.pdf#page=12','Будут ли распространяться запахи в герметично закрытом подвальном помещении, где совершенно нет сквозняков?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',5,4,'SUFFICIENT','б',false,12,'DETAILED','','kirik7.pdf#page=12','Как можно объяснить, что твердые тела сохраняют собственную форму?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',6,4,'SUFFICIENT','а',false,12,'DETAILED','','kirik7.pdf#page=12','На чем основан метод сварки, применяемый при соединении двух металлических деталей?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',6,4,'SUFFICIENT','б',false,12,'DETAILED','','kirik7.pdf#page=12','Почему газы не имеют собственной формы и постоянного объема?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',1,4,'HIGH','а',false,12,'DETAILED','','kirik7.pdf#page=12','Открытый сосуд с эфиром уравновесили на весах и оставили в покое. Через некоторое время равновесие весов нарушилось. Почему?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',1,4,'HIGH','б',false,12,'DETAILED','','kirik7.pdf#page=12','Лед расплавили и превратили в воду. Эту воду нагрели до кипения и полностью испарили. Изменились или нет молекулы воды в этих превращениях? Что изменилось в характере движения и взаимодействия молекул?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',2,4,'HIGH','а',false,13,'DETAILED','','kirik7.pdf#page=13','Представьте себе, что у вас есть два сосуда: один с прозрачной жидкостью, другой с бесцветным газом. Сможете ли вы, глядя на них, определить, в каком сосуде находится жидкость? Как?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',2,4,'HIGH','б',false,13,'DETAILED','','kirik7.pdf#page=13','Почему при сгибании прутика паяльного олова слышен характерный треск?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',3,4,'HIGH','а',false,13,'DETAILED','','kirik7.pdf#page=13','Переверните стакан вверх дном и медленно погружайте его в широкий сосуд с водой. Наблюдайте за объемом воздуха в нем при погружении. Какие выводы можно сделать? Как объяснить наблюдаемое?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',3,4,'HIGH','б',false,13,'DETAILED','','kirik7.pdf#page=13','Может ли медь быть жидкой, а ртуть твердой? При каких условиях?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',4,4,'HIGH','а',false,13,'DETAILED','','kirik7.pdf#page=13','Сравните между собой жидкое и газообразное состояние вещества. Что общего и в чем различия в этих состояниях?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',4,4,'HIGH','б',false,13,'DETAILED','','kirik7.pdf#page=13','Почему при склеивании и паянии применяют жидкий клей и расплавленный припой?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',5,4,'HIGH','а',false,13,'DETAILED','','kirik7.pdf#page=13','Объясните на основе молекулярной теории, чем отличается холодная вода от теплой.'),
                                                                                                                                               ('Диффузия. Три состояния вещества',5,4,'HIGH','б',false,13,'DETAILED','','kirik7.pdf#page=13','Что надо сделать, чтобы вынуть стальной болт, застрявший в бронзовой втулке?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',6,4,'HIGH','а',false,13,'DETAILED','','kirik7.pdf#page=13','При неосторожном пользовании медицинским термометром его можно разбить. Почему в таких случаях рекомендуется как можно быстрее собрать пролитую ртуть, всю до мельчайших капелек?'),
                                                                                                                                               ('Диффузия. Три состояния вещества',6,4,'HIGH','б',false,13,'DETAILED','','kirik7.pdf#page=13','Что произошло бы с телами, если бы вдруг их молекулы перестали притягиваться друг к другу? перестали отталкиваться друг от друга?');
INSERT INTO tasks (title,task_number,self_task_number,task_level,task_letter,has_image,page_number,answer_type,answer,page_link,task_text) VALUES
                                                                                                                                               ('Относительность движения. Траектория и путь',1,5,'INITIAL',' ',false,14,'DETAILED','','kirik7.pdf#page=14','Какие тела движутся прямолинейно: поезд вдоль платформы станции, лифт, искусственный спутник Земли?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',2,5,'INITIAL',' ',false,14,'DETAILED','','kirik7.pdf#page=14','Какие тела движутся криволинейно: конец минутной стрелки часов, выпущенный из рук камень, Земля по своей орбите?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',3,5,'INITIAL',' ',false,14,'DETAILED','','kirik7.pdf#page=14','На столике в вагоне движущегося поезда лежит книга. Относительно каких тел книга находится в покое: а) столика; б) рельсов; в) пола вагона?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',4,5,'INITIAL',' ',false,14,'DETAILED','','kirik7.pdf#page=14','Корабль подплывает к пристани. Относительно каких тел пассажиры, стоящие на палубе этого корабля, находятся в движении: а) реки; б) палубы корабля; в) берега?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',5,5,'INITIAL',' ',false,14,'DETAILED','','kirik7.pdf#page=14','Одинаковые ли пути проходят электровоз и последний вагон поезда?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',6,5,'INITIAL',' ',false,14,'DETAILED','','kirik7.pdf#page=14','Велосипед едет по ровной прямой дороге. Какие детали велосипеда движутся относительно земли по прямолинейным траекториям: а) седло; б) точка обода колеса; в) рама велосипеда?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',1,5,'MIDDLE',' ',false,14,'DETAILED','','kirik7.pdf#page=14','Какого вида движения совершают различные части швейной машины?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',2,5,'MIDDLE',' ',false,14,'DETAILED','','kirik7.pdf#page=14','Какую форму имеют траектории движения детей, катающихся на карусели?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',3,5,'MIDDLE',' ',false,14,'DETAILED','','kirik7.pdf#page=14','Какие части велосипеда движутся по прямолинейным траекториям и какие — по криволинейным, когда на нем едут по ровной прямой дороге?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',4,5,'MIDDLE',' ',false,14,'DETAILED','','kirik7.pdf#page=14','Приведите два примера тел, относительно которых движется и относительно которых покоится пассажир поезда, движущегося между станциями.'),
                                                                                                                                               ('Относительность движения. Траектория и путь',5,5,'MIDDLE',' ',false,14,'DETAILED','','kirik7.pdf#page=14','Велосипедист проехал путь в 500 м. Одинаковые ли пути пройдены при этом передними и задним колесами велосипеда?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',6,5,'MIDDLE',' ',false,14,'DETAILED','','kirik7.pdf#page=14','Движутся или покоятся относительно друг друга пассажиры метро, находящиеся на двух эскалаторах: а) движущихся в одном направлении; б) движущихся в разных направлениях?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',1,5,'SUFFICIENT',' ',false,15,'DETAILED','','kirik7.pdf#page=15','Самолет, летящий со скоростью 900 км/ч, во время полета заправляется горючим с другого самолета. С какой скоростью движется при этом самолет-заправщик?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',2,5,'SUFFICIENT',' ',false,15,'DETAILED','','kirik7.pdf#page=15','Группа самолетов выполняет одновременно фигуры высшего пилотажа, сохраняя заданный строй. Что можно сказать о движении самолетов относительно друг друга?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',3,5,'SUFFICIENT',' ',false,15,'DETAILED','','kirik7.pdf#page=15','Какую траекторию описывает при движении автомобиля его фара, точка обода колеса, центр колеса: а) относительно прямолинейного шоссе; б) относительно центра колеса?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',4,5,'SUFFICIENT',' ',false,15,'DETAILED','','kirik7.pdf#page=15','Нарисуйте траекторию движения произвольной точки на ободе колеса железнодорожного вагона относительно вагона; относительно земли.'),
                                                                                                                                               ('Относительность движения. Траектория и путь',5,5,'SUFFICIENT',' ',false,15,'DETAILED','','kirik7.pdf#page=15','Рассмотрите движение конца минутной и секундной стрелок секундомера. Что общего и в чем различие в этих движениях? Изобразите траекторию движения стрелок.'),
                                                                                                                                               ('Относительность движения. Траектория и путь',6,5,'SUFFICIENT',' ',false,15,'DETAILED','','kirik7.pdf#page=15','Нарисуйте двумя разными цветами примерные траектории своей левой ступни и левой кисти при ходьбе, рассматривая движение относительно земли.'),
                                                                                                                                               ('Относительность движения. Траектория и путь',1,5,'HIGH',' ',false,15,'DETAILED','','kirik7.pdf#page=15','Ветер несет воздушный шар на север. В какую сторону отклоняется флаг, которым украшен шар?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',2,5,'HIGH',' ',false,15,'DETAILED','','kirik7.pdf#page=15','Спортивный судья стоит на линии финиша. Должен ли он пустить секундомер в тот момент, когда увидит огонь стартового пистолета, или в тот момент, когда он услышит выстрел?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',3,5,'HIGH',' ',false,15,'DETAILED','','kirik7.pdf#page=15','Летчик-спортсмен сумел посадить самолет на крышу легкового автомобиля. При каком физическом условии это возможно?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',4,5,'HIGH',' ',false,15,'DETAILED','','kirik7.pdf#page=15','На одной из линий метрополитена поезд каждый свой рейс в одну сторону совершает за 30 мин. Можно ли считать его движение равномерным? Каков главный признак равномерного движения?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',5,5,'HIGH',' ',false,15,'DETAILED','','kirik7.pdf#page=15','Поезд едет со скоростью 20 м/с. По платформе поезда едет мотоциклист так, что при этом он покоится относительно телеграфных столбов на обочине дороги. Сколько времени может продолжаться такой «покой», если длина вагона 20 м?'),
                                                                                                                                               ('Относительность движения. Траектория и путь',6,5,'HIGH',' ',false,15,'DETAILED','','kirik7.pdf#page=15','Автомобиль делает поворот налево по дуге окружности радиусом 30 м. Нарисуйте двумя различными цветами траекторию левого и правого передних колес при таком движении (размером самих колес пренебречь). Какое колесо прошло больший путь? Насколько больший? Расстояние между передними колесами равно 2 м.');
INSERT INTO tasks (title,task_number,self_task_number,task_level,task_letter,has_image,page_number,answer_type,answer,page_link,task_text) VALUES
                                                                                                                                               ('Скорость, путь и время',1,6,'INITIAL',' ',false,16,'DETAILED','','kirik7.pdf#page=16','Тележка движется со скоростью 1 м/с. Какова ее скорость в километрах в час?'),
                                                                                                                                               ('Скорость, путь и время',2,6,'INITIAL',' ',false,16,'DETAILED','','kirik7.pdf#page=16','Выразите в метрах в секунду скорость 7,2 км/ч.'),
                                                                                                                                               ('Скорость, путь и время',4,6,'INITIAL',' ',false,16,'DETAILED','','kirik7.pdf#page=16','Выразите в метрах в секунду скорость 18 км/ч.'),
                                                                                                                                               ('Скорость, путь и время',5,6,'INITIAL',' ',false,16,'DETAILED','','kirik7.pdf#page=16','Какая скорость больше: 5 м/с или 36 км/ч?'),
                                                                                                                                               ('Скорость, путь и время',6,6,'INITIAL',' ',false,16,'DETAILED','','kirik7.pdf#page=16','Какая скорость больше: 72 км/ч или 10 м/с?'),
                                                                                                                                               ('Скорость, путь и время',1,6,'MIDDLE',' ',false,16,'SHORT','10 км/ч','kirik7.pdf#page=16','Вычислите скорость лыжника, прошедшего 20 км за 2 ч.'),
                                                                                                                                               ('Скорость, путь и время',2,6,'MIDDLE',' ',false,16,'SHORT','600 м','kirik7.pdf#page=16','В течение 30 с поезд двигался равномерно со скоростью 72 км/ч. Какой путь прошел поезд за это время?'),
                                                                                                                                               ('Скорость, путь и время',3,6,'MIDDLE',' ',false,16,'SHORT','30 с','kirik7.pdf#page=16','Лифт поднимается равномерно со скоростью 3 м/с. За сколько времени поднимется лифт на высоту 90 м?'),
                                                                                                                                               ('Скорость, путь и время',4,6,'MIDDLE',' ',false,16,'SHORT','25 м/с','kirik7.pdf#page=16','Листья, поднятые ветром, за 5 мин, двигаясь равномерно, переместились на расстояние 7500 м. Какова скорость урагана?'),
                                                                                                                                               ('Скорость, путь и время',5,6,'MIDDLE',' ',false,16,'SHORT','400 с','kirik7.pdf#page=16','Сколько времени займет спуск на парашюте с высоты 2 км при скорости равномерного снижения 5 м/с?'),
                                                                                                                                               ('Скорость, путь и время',6,6,'MIDDLE',' ',false,16,'SHORT','4200 км','kirik7.pdf#page=16','Современный реактивный самолет развивает скорость до 1200 км/ч. Какое расстояние он пролетит за 3 ч 30 мин?'),
                                                                                                                                               ('Скорость, путь и время',1,6,'SUFFICIENT',' ',false,16,'SHORT','3,6 км','kirik7.pdf#page=16','Трактор за первые 5 мин проехал 600 м. Какой путь он пройдет за 0,5 ч, двигаясь с той же скоростью?'),
                                                                                                                                               ('Скорость, путь и время',2,6,'SUFFICIENT',' ',false,16,'SHORT','8 м/с','kirik7.pdf#page=16','Один велосипедист 12 с двигался со скоростью 6 м/с, а второй проехал этот же участок пути за 9 с. Какова скорость второго велосипедиста на этом участке пути?'),
                                                                                                                                               ('Скорость, путь и время',3,6,'SUFFICIENT',' ',false,16,'SHORT','30 км/ч','kirik7.pdf#page=16','Автомобиль ехал 0,5 ч со скоростью 90 км/ч. С какой скоростью должен ехать велосипедист, чтобы проехать тот же участок пути за 1 ч 30 мин?'),
                                                                                                                                               ('Скорость, путь и время',4,6,'SUFFICIENT',' ',false,16,'SHORT','1 ч 40 мин','kirik7.pdf#page=16','Велосипедист за 40 мин проехал 10 км. За сколько времени он проедет еще 25 км, двигаясь с той же скоростью?'),
                                                                                                                                               ('Скорость, путь и время',5,6,'SUFFICIENT',' ',false,16,'SHORT','2,7 км','kirik7.pdf#page=16','Автомобиль за первые 10 мин проехал 900 м. Какой путь он пройдет за 0,5 ч, двигаясь с той же скоростью?'),
                                                                                                                                               ('Скорость, путь и время',6,6,'SUFFICIENT',' ',false,16,'SHORT','48 см','kirik7.pdf#page=16','В подрывной технике применяют бикфордов шнур. Какой длины надо взять шнур, чтобы после его загорания успеть отбежать на расстояние 300 м? Скорость бега 5 м/с, а скорость распространения пламени — 0,8 см/с.'),
                                                                                                                                               ('Скорость, путь и время',1,6,'HIGH',' ',false,17,'SHORT','60 км/ч','kirik7.pdf#page=17','Из города в одну сторону выехали мотоциклист и вслед за ним через некоторое время автомобиль. Скорость автомобиля 90 км/ч, скорость мотоциклиста 30 км/ч. С какой скоростью сближаются мотоциклист и автомобиль? С какой скоростью они будут удаляться друг от друга после встречи?'),
                                                                                                                                               ('Скорость, путь и время',2,6,'HIGH',' ',false,17,'SHORT','2,5 ч','kirik7.pdf#page=17','Человек полпути проехал на велосипеде со скоростью 25 км/ч, а остаток пути прошел со скоростью 5 км/ч. Сколько времени он шел, если весь путь занял 3 ч?'),
                                                                                                                                               ('Скорость, путь и время',3,6,'HIGH',' ',false,17,'SHORT','1,8 ч','kirik7.pdf#page=17','Из населенного пункта по одной прямой дороге вышел путник и спустя 1,5 часа выехал всадник. Скорость путника 5 км/ч, скорость всадника 30 км/ч. Постройте на одном чертеже графики зависимости пути от времени для путника и всадника и, пользуясь этими графиками, найдите через какое время после начала своего движения всадник догонит путника.'),
                                                                                                                                               ('Скорость, путь и время',4,6,'HIGH',' ',false,17,'SHORT','3,3 ч','kirik7.pdf#page=17','Из города вышел турист, а через 3 часа вслед за ним по той же прямой дороге выехал велосипедист. Велосипедист едет со скоростью 30 км/ч, турист идет со скоростью 6 км/ч. Постройте на одном чертеже графики зависимости пути от времени для туриста и велосипедиста и, пользуясь ими, найдите через какое время после выезда велосипедиста расстояние между велосипедистом и туристом будет равно 10 км.'),
                                                                                                                                               ('Скорость, путь и время',5,6,'HIGH',' ',false,17,'SHORT','40 км, 100 км','kirik7.pdf#page=17','Из города по одной прямой дороге одновременно выехали два автомобиля. Скорость первого автомобиля 120 км/ч, второго — 80 км/ч. Постройте на одном чертеже графики зависимости пути от времени для обоих автомобилей. Пользуясь графиками, найдите расстояние между автомобилями через: а) 1 ч после начала движения; б) через 2 ч 30 мин после начала движения.'),
                                                                                                                                               ('Скорость, путь и время',6,6,'HIGH',' ',false,17,'SHORT','200 м, 20 м/с','kirik7.pdf#page=17','Поезд проходит мимо наблюдателя в течение 10 с, а по мосту длиной 400 м — в течение 30 с. Определить длину и скорость поезда.');
INSERT INTO tasks (title,task_number,self_task_number,task_level,task_letter,has_image,page_number,answer_type,answer,page_link,task_text) VALUES
                                                                                                                                               ('Движение нескольких тел одновременно',1,7,'SUFFICIENT',' ',false,17,'SHORT','4,3 с','kirik7.pdf#page=17','Сколько времени пассажир, сидящий у окна движущегося поезда — его скорость 54 км/ч, — будет видеть проходящий мимо него встречный поезд, скорость которого 72 км/ч, если его длина 150 м?'),
                                                                                                                                               ('Движение нескольких тел одновременно',2,7,'SUFFICIENT',' ',false,17,'SHORT','60 с','kirik7.pdf#page=17','По параллельным путям в одну сторону движутся два электропоезда. Скорость первого поезда 54 км/ч, второго — 10 м/с. Сколько времени будет продолжаться обгон, если длина каждого поезда 150 м?'),
                                                                                                                                               ('Движение нескольких тел одновременно',3,7,'SUFFICIENT',' ',false,18,'SHORT','490 м','kirik7.pdf#page=18','Два поезда движутся навстречу друг другу со скоростями 72 км/ч и 54 км/ч. Пассажир, находящийся в первом поезде, замечает, что второй поезд проходит мимо него в течение 14 с. Какова длина второго поезда?'),
                                                                                                                                               ('Движение нескольких тел одновременно',4,7,'SUFFICIENT',' ',false,18,'SHORT','10 с','kirik7.pdf#page=18','Сколько времени мимо мотоциклиста, едущего со скоростью 63 км/ч, будет проезжать встречная колонна автомобилей длиной 300 м, имеющая скорость 45 км/ч?'),
                                                                                                                                               ('Движение нескольких тел одновременно',5,7,'SUFFICIENT',' ',false,18,'SHORT','10 м/с','kirik7.pdf#page=18','Автоколонна длиной 200 м и встречный автомобиль имеют равные скорости. С какой скоростью движется автомобиль, если пассажир в нем отметил, что мимо колонны автомобиль двигался 10 с?'),
                                                                                                                                               ('Движение нескольких тел одновременно',6,7,'SUFFICIENT',' ',false,18,'SHORT','5 м/с','kirik7.pdf#page=18','Поезд длиной 240 м, двигаясь равномерно, прошел мост за 2 мин. Какова скорость поезда, если длина моста 360 м?'),
                                                                                                                                               ('Движение нескольких тел одновременно',1,7,'HIGH',' ',false,18,'SHORT','14 мин','kirik7.pdf#page=18','Группа туристов, двигаясь цепочкой по обочине дороги со скоростью 3,6 км/ч, растянулась на 200 м. Замыкающий посылает велосипедиста к вожатому, который находится впереди группы. Велосипедист едет со скоростью 7 м/с; выполнив поручение, он тут же возвращается к замыкающему группы с той же скоростью. Через сколько времени после получения поручения велосипедист вернулся обратно?'),
                                                                                                                                               ('Движение нескольких тел одновременно',2,7,'HIGH',' ',false,18,'SHORT','58,3 с','kirik7.pdf#page=18','Путешественник, глядя в окно вагона, заметил, что два встречных поезда прошли мимо него через 7 мин один после другого. Через какой промежуток времени один после другого отправились эти поезда со станции, если все три поезда движутся с одинаковыми скоростями?'),
                                                                                                                                               ('Движение нескольких тел одновременно',3,7,'HIGH',' ',false,18,'SHORT','5 м/с','kirik7.pdf#page=18','Из двух пунктов, расстояние между которыми 100 м, одновременно навстречу друг другу начали двигаться два тела. Скорость одного из них 20 м/с. Какова скорость второго тела, если они встретились через 4 с?'),
                                                                                                                                               ('Движение нескольких тел одновременно',4,7,'HIGH',' ',false,18,'SHORT','2 км/ч','kirik7.pdf#page=18','Моторная лодка проходит по реке от пункта A до пункта B расстояние за 4 часа, а обратно — за 5 часов. Определите скорость течения реки, если расстояние между пунктами 80 км. Скорость лодки относительно воды оставалась все время одной и той же.'),
                                                                                                                                               ('Движение нескольких тел одновременно',5,7,'HIGH',' ',false,18,'SHORT','6 ч','kirik7.pdf#page=18','Моторная лодка проходит расстояние между двумя пунктами A и B по течению реки за 3 часа, а плот — за 12 часов. Сколько времени моторная лодка затратит на обратный путь?'),
                                                                                                                                               ('Движение нескольких тел одновременно',6,7,'HIGH',' ',false,18,'SHORT','20 сут','kirik7.pdf#page=18','Теплоход проходит расстояние между двумя пунктами на реке вниз по течению за 60 часов, а обратно — за 80 часов. Сколько суток между этими пунктами плывут плоты?');
INSERT INTO tasks (title,task_number,self_task_number,task_level,task_letter,has_image,page_number,answer_type,answer,page_link,task_text) VALUES
                                                                                                                                               ('Средняя скорость',1,8,'INITIAL',' ',false,19,'SHORT','8 км/ч','kirik7.pdf#page=19','Найти среднюю скорость лыжника, который прошел расстояние 24 км за 3 часа.'),
                                                                                                                                               ('Средняя скорость',2,8,'INITIAL',' ',false,19,'SHORT','50 км/ч','kirik7.pdf#page=19','Автомобиль проехал 60 км за 1 ч, а потом еще 240 км за 5 ч. Какова средняя скорость на всем пути?'),
                                                                                                                                               ('Средняя скорость',3,8,'INITIAL',' ',false,19,'SHORT','60 км','kirik7.pdf#page=19','Какой путь проедет велосипедист за 3 ч, если его средняя скорость 20 км/ч?'),
                                                                                                                                               ('Средняя скорость',4,8,'INITIAL',' ',false,19,'SHORT','22 км/ч','kirik7.pdf#page=19','Какова средняя скорость теплохода, если за 7 ч он проплыл расстояние 154 км?'),
                                                                                                                                               ('Средняя скорость',5,8,'INITIAL',' ',false,19,'SHORT','2 км/ч','kirik7.pdf#page=19','Турист прошел 2 км за 1 час, а затем еще 3 км за 1,5 ч. Какова средняя скорость на всем пути?'),
                                                                                                                                               ('Средняя скорость',6,8,'INITIAL',' ',false,19,'SHORT','20 км/ч','kirik7.pdf#page=19','Найти среднюю скорость велосипедиста, который проехал расстояние 40 км за 2 ч.'),
                                                                                                                                               ('Средняя скорость',1,8,'MIDDLE',' ',false,19,'SHORT','32 км/ч','kirik7.pdf#page=19','Автобус первые 4 км пути проехал за 12 мин, а следующие 12 км — за 18 мин. Определите среднюю скорость автобуса на всем пути.'),
                                                                                                                                               ('Средняя скорость',2,8,'MIDDLE',' ',false,19,'SHORT','4,8 км/ч','kirik7.pdf#page=19','Вагон, двигаясь равномерно под уклон с сортировочной горки, проходит 120 м за 10 с. Скатившись с горки, он проходит до полной остановки еще 360 м за 1,5 мин. Определите среднюю скорость вагона за все время движения.'),
                                                                                                                                               ('Средняя скорость',3,8,'MIDDLE',' ',false,19,'SHORT','35 км/ч','kirik7.pdf#page=19','Мотоциклист за первые 10 мин движения проехал путь 5 км, а за следующие 20 мин — 12,5 км. Какова средняя скорость мотоциклиста на всем пути?'),
                                                                                                                                               ('Средняя скорость',4,8,'MIDDLE',' ',false,19,'SHORT','13 м/с','kirik7.pdf#page=19','Двигаясь по шоссе, велосипедист проехал 900 м со скоростью 15 м/с, а затем по плохой дороге проехал 400 м со скоростью 10 м/с. С какой средней скоростью он проехал весь путь?'),
                                                                                                                                               ('Средняя скорость',5,8,'MIDDLE',' ',false,19,'SHORT','8 км/ч, 4 км/ч','kirik7.pdf#page=19','Турист за 25 мин прошел 1,2 км, затем полчаса отдыхал, а затем пробежал еще 800 м за 5 мин. Какова была его средняя скорость на всем пути? Какова была бы его средняя скорость, если бы он не отдыхал?'),
                                                                                                                                               ('Средняя скорость',6,8,'MIDDLE',' ',false,19,'SHORT','8,75 м/с','kirik7.pdf#page=19','Трамвай прошел первые 100 м со средней скоростью 5 м/с, а следующие 600 м со средней скоростью 10 м/с. Определите среднюю скорость трамвая на всем пути.'),
                                                                                                                                               ('Средняя скорость',1,8,'SUFFICIENT',' ',false,20,'SHORT','45 км/ч','kirik7.pdf#page=20','Из одного пункта в другой мотоциклист двигался со скоростью 60 км/ч, обратный путь был им проделан со скоростью 10 м/с. Определите среднюю скорость мотоциклиста за все время движения.'),
                                                                                                                                               ('Средняя скорость',2,8,'SUFFICIENT',' ',false,20,'SHORT','68,6 км/ч','kirik7.pdf#page=20','Мотоциклист полпути ехал со скоростью 80 км/ч, а остаток пути — со скоростью 60 км/ч. Какой была средняя скорость мотоциклиста на всем пути?'),
                                                                                                                                               ('Средняя скорость',3,8,'SUFFICIENT',' ',false,20,'SHORT','81,8 км/ч','kirik7.pdf#page=20','Поезд двигался на подъеме со средней скоростью 60 км/ч, а на спуске его средняя скорость составила 100 км/ч. Определить среднюю скорость на всем участке пути, если учесть, что спуск в два раза длиннее подъема.'),
                                                                                                                                               ('Средняя скорость',4,8,'SUFFICIENT',' ',false,20,'SHORT','24 м/с','kirik7.pdf#page=20','Автомобиль двигался первую половину пути со скоростью 20 м/с, а вторую — со скоростью 30 м/с. Найти среднюю скорость автомобиля на всем пути.'),
                                                                                                                                               ('Средняя скорость',5,8,'SUFFICIENT',' ',false,20,'SHORT','6 км/ч','kirik7.pdf#page=20','Велосипедист проехал первую половину пути со скоростью 12 км/ч, а вторую половину пути с какой-то другой скоростью. Как велика эта скорость, если известно, что средняя скорость его движения на всем пути равна 8 км/ч?'),
                                                                                                                                               ('Средняя скорость',6,8,'SUFFICIENT',' ',false,20,'SHORT','9 км/ч','kirik7.pdf#page=20','Первую половину пути автобус шел со скоростью, в 8 раз большей, чем вторую. Средняя скорость автобуса на всем пути равна 16 км/ч. Определите скорость автобуса на второй половине пути.'),
                                                                                                                                               ('Средняя скорость',1,8,'HIGH',' ',false,20,'SHORT','50 км/ч','kirik7.pdf#page=20','Автомобиль двигался первую половину времени со скоростью 60 км/ч, а вторую — со скоростью 40 км/ч. Определите среднюю скорость движения автомобиля на всем пути.'),
                                                                                                                                               ('Средняя скорость',2,8,'HIGH',' ',false,20,'SHORT','6 км/ч','kirik7.pdf#page=20','Путешественник два часа ехал на велосипеде, а потом велосипед сломался, и путешественник шесть часов шел пешком. Какой была его средняя скорость, если ехал он втрое быстрее, чем шел, а шел со скоростью 4 км/ч?'),
                                                                                                                                               ('Средняя скорость',3,8,'HIGH',' ',false,20,'SHORT','4 км/ч','kirik7.pdf#page=20','Пешеход две трети времени своего движения шел со скоростью 3 км/ч. Оставшееся время — со скоростью 6 км/ч. Определите среднюю скорость пешехода.'),
                                                                                                                                               ('Средняя скорость',4,8,'HIGH',' ',false,20,'SHORT','40 км/ч','kirik7.pdf#page=20','Автомобиль проехал половину пути со скоростью 60 км/ч, оставшуюся часть пути он половину времени шел со скоростью 15 км/ч, а последний участок — со скоростью 45 км/ч. Найти среднюю скорость автомобиля на всем пути.'),
                                                                                                                                               ('Средняя скорость',5,8,'HIGH',' ',false,20,'SHORT','14 км/ч','kirik7.pdf#page=20','Велосипедист половину времени всего движения ехал со скоростью 20 км/ч, половину оставшегося пути со скоростью 15 км/ч, а последний участок — шел со скоростью 6 км/ч. Какова средняя скорость на всем пути?'),
                                                                                                                                               ('Средняя скорость',6,8,'HIGH',' ',false,20,'SHORT','5/8 пути и 1/4 времени движения','kirik7.pdf#page=20','Путешественник ехал сначала на лошади, а потом на осле. Какую часть пути и какую часть всего времени движения он ехал на лошади, если средняя скорость путешественника оказалась равной 12 км/ч, скорость езды на лошади 30 км/ч, а на осле — 6 км/ч?');
INSERT INTO tasks (title,task_number,self_task_number,task_level,task_letter,has_image,page_number,answer_type,answer,page_link,task_text) VALUES
                                                                                                                                               ('Инерция. Масса',1,9,'INITIAL',' ',false,21,'DETAILED','','kirik7.pdf#page=21','В какую сторону падает споткнувшийся человек?'),
                                                                                                                                               ('Инерция. Масса',2,9,'INITIAL',' ',false,21,'DETAILED','','kirik7.pdf#page=21','В какую сторону отклоняются пассажиры относительно автобуса при повороте его вправо?'),
                                                                                                                                               ('Инерция. Масса',3,9,'INITIAL',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Почему нельзя перебегать улицу перед близко идущим транспортом?'),
                                                                                                                                               ('Инерция. Масса',4,9,'INITIAL',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Куда отклоняются пассажиры при внезапной остановке автобуса?'),
                                                                                                                                               ('Инерция. Масса',5,9,'INITIAL',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Изменяется ли масса воды при переливании ее из банки в ведро?'),
                                                                                                                                               ('Инерция. Масса',6,9,'INITIAL',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Гирю подняли на высоту 2 м от пола. Изменилась ли при этом ее масса?'),
                                                                                                                                               ('Инерция. Масса',7,9,'INITIAL',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Выразите в килограммах массы тел: 2,5 т; 2000 г; 150 г.'),
                                                                                                                                               ('Инерция. Масса',8,9,'INITIAL',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Выразите в граммах следующие массы: 1,2 кг; 0,6 кг; 800 мг.'),
                                                                                                                                               ('Инерция. Масса',1,9,'MIDDLE',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Почему при поворотах водитель замедляет ход машины?'),
                                                                                                                                               ('Инерция. Масса',2,9,'MIDDLE',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Всадник быстро скачет на лошади. Что будет с всадником, если лошадь споткнется?'),
                                                                                                                                               ('Инерция. Масса',3,9,'MIDDLE',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Тело переместили с Земли на Луну. Изменилась ли при этом масса тела?'),
                                                                                                                                               ('Инерция. Масса',4,9,'MIDDLE',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Сильно надуйте шарик и, не завязывая его, отпустите. Почему он, сдуваясь, улетает?'),
                                                                                                                                               ('Инерция. Масса',5,9,'MIDDLE',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Почему автомобилю трудно тронуться с места на обледенелой улице?'),
                                                                                                                                               ('Инерция. Масса',6,9,'MIDDLE',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Тело перенесли с поверхности Земли в открытый космос. Изменилась ли при этом масса тела?'),
                                                                                                                                               ('Инерция. Масса',7,9,'MIDDLE',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Сидевшая на ветке птица вспорхнула и улетела. Куда и в какой момент отклонилась ветка? Почему?'),
                                                                                                                                               ('Инерция. Масса',8,9,'MIDDLE',' ',false,21,'DETAILED','','kirik7.pdf#page=21','Может ли масса какого-нибудь тела быть равной нулю?'),
                                                                                                                                               ('Инерция. Масса',1,9,'SUFFICIENT','а',false,21,'DETAILED','','kirik7.pdf#page=21','Почему капли дождя при резком встряхивании слетают с одежды?'),
                                                                                                                                               ('Инерция. Масса',1,9,'SUFFICIENT','б',false,21,'SHORT','6,9 см/с','kirik7.pdf#page=21','Мальчик массой 46 кг прыгнул на берег со скоростью 1,5 м/с с неподвижного плота массой 1 т. Какую скорость приобрел плот?'),
                                                                                                                                               ('Инерция. Масса',2,9,'SUFFICIENT','а',false,21,'DETAILED','','kirik7.pdf#page=21','На наклонной плоскости лежит брусок. С какими телами он взаимодействует?'),
                                                                                                                                               ('Инерция. Масса',2,9,'SUFFICIENT','б',false,21,'SHORT','45 см/с','kirik7.pdf#page=21','Массы тележек 1 и 3 кг, скорости их равны нулю. При взаимодействии большая тележка приобрела скорость 15 см/с. Какую скорость приобрела меньшая тележка?'),
                                                                                                                                               ('Инерция. Масса',3,9,'SUFFICIENT','а',false,22,'DETAILED','','kirik7.pdf#page=22','К потолку каюты равномерно идущего теплохода подвешен шар. Какое произойдет изменение в положении шара, если теплоход пойдет: а) ускоренно; б) повернет в сторону; в) внезапно остановится?'),
                                                                                                                                               ('Инерция. Масса',3,9,'SUFFICIENT','б',false,22,'DETAILED','','kirik7.pdf#page=22','Гирю опустили в сосуд с водой. Изменилась ли масса гири?'),
                                                                                                                                               ('Инерция. Масса',4,9,'SUFFICIENT','а',false,22,'DETAILED','','kirik7.pdf#page=22','Почему при выстреле из орудия снаряд и орудие приобретают разные скорости? Скорость какого тела больше?'),
                                                                                                                                               ('Инерция. Масса',4,9,'SUFFICIENT','б',false,22,'SHORT','0,2 кг','kirik7.pdf#page=22','При взаимодействии двух тележек скорости их изменились на 20 см/с и 60 см/с. Масса большей тележки 0,6 кг. Чему равна масса меньшей тележки?'),
                                                                                                                                               ('Инерция. Масса',5,9,'SUFFICIENT','а',false,22,'DETAILED','','kirik7.pdf#page=22','Автомобиль разгоняется, отталкиваясь от дороги. А от чего отталкивается ракета, разгоняясь в космосе?'),
                                                                                                                                               ('Инерция. Масса',5,9,'SUFFICIENT','б',false,22,'SHORT','16 т','kirik7.pdf#page=22','После орудийного выстрела снаряд массой 20 кг полетел со скоростью 800 м/с. Какова масса орудия, если оно вследствие отдачи начало двигаться со скоростью 1 м/с?'),
                                                                                                                                               ('Инерция. Масса',6,9,'SUFFICIENT','а',false,22,'DETAILED','','kirik7.pdf#page=22','Подголовник, прикрепленный к спинке сидения автомобиля, удерживает голову человека от отклонения назад. В каких аварийных ситуациях помогает этот подголовник и от каких травм он предохраняет?'),
                                                                                                                                               ('Инерция. Масса',6,9,'SUFFICIENT','б',false,22,'SHORT','2 м/с','kirik7.pdf#page=22','Из орудия массой 5 т вылетел снаряд массой 25 кг. При этом снаряд получил скорость 400 м/с относительно земли. Какую скорость получило орудие при отдаче?'),
                                                                                                                                               ('Инерция. Масса',1,9,'HIGH','а',false,22,'SHORT','10 кг','kirik7.pdf#page=22','Порожняя тележка массой 2 кг, двигаясь со скоростью 2 м/с, столкнулась с груженой тележкой. Вследствие столкновения порожняя тележка остановилась, а груженая начала двигаться со скоростью 0,4 м/с. Какая масса груженой тележки?'),
                                                                                                                                               ('Инерция. Масса',1,9,'HIGH','б',false,22,'DETAILED','','kirik7.pdf#page=22','Изменяется ли масса воды при ее замерзании?'),
                                                                                                                                               ('Инерция. Масса',2,9,'HIGH','а',false,22,'SHORT','40 м/с','kirik7.pdf#page=22','Снаряд, пущенный вертикально вверх, разорвался в верхней точке траектории на два осколка массой 1 кг и 4 кг. Первый осколок полетел с начальной скоростью 160 м/с относительно земли. С какой начальной скоростью полетел второй осколок?'),
                                                                                                                                               ('Инерция. Масса',2,9,'HIGH','б',false,22,'DETAILED','','kirik7.pdf#page=22','Изменилась ли масса сена в копне, когда это сено спрессовали в тюк? Что изменилось?'),
                                                                                                                                               ('Инерция. Масса',3,9,'HIGH','а',false,22,'SHORT','80 кг','kirik7.pdf#page=22','Человек, бегущий со скоростью 8 м/с, догнал тележку, двигающуюся со скоростью 2 м/с, и вскочил в нее. В результате скорость тележки стала 6 м/с. Какова масса человека, если масса тележки 40 кг?'),
                                                                                                                                               ('Инерция. Масса',3,9,'HIGH','б',false,22,'DETAILED','','kirik7.pdf#page=22','Из овечьей шерсти скатали валенки. Сравните массы шерсти и валенок, если отходов не было. Что изменилось?'),
                                                                                                                                               ('Инерция. Масса',4,9,'HIGH','а',false,22,'SHORT','6 м/с','kirik7.pdf#page=22','Два барана с разбегу столкнулись лбами и покатились клубком по земле со скоростью 2 м/с. Скорость первого барана была равна 10 м/с. Какой была скорость второго барана перед столкновением, если массы баранов равны?'),
                                                                                                                                               ('Инерция. Масса',4,9,'HIGH','б',false,22,'DETAILED','','kirik7.pdf#page=22','В стакане находится смесь воды и снега. Изменится ли масса содержимого в стакане, если снег растает?'),
                                                                                                                                               ('Инерция. Масса',5,9,'HIGH','а',false,23,'SHORT','Массы шаров равны','kirik7.pdf#page=23','Два шара, двигавшиеся навстречу друг другу, сталкиваются. В результате первый шар, имевший скорость 5 м/с, остановился. Второй же шар, имевший 3 м/с, отлетел назад со скоростью 2 м/с. Масса какого шара больше и во сколько раз?'),
                                                                                                                                               ('Инерция. Масса',5,9,'HIGH','б',false,23,'DETAILED','','kirik7.pdf#page=23','Воздух под поршнем насоса сжали. Изменилась ли масса воздуха?'),
                                                                                                                                               ('Инерция. Масса',6,9,'HIGH','а',false,23,'SHORT','50 м/с','kirik7.pdf#page=23','Горизонтально летящая пуля массой 10 г попала в лежащий на гладкой горизонтальной поверхности деревянный брусок массой 500 г и застряла там. Какова была скорость пули, если брусок после выстрела приобрел скорость 10 м/с?'),
                                                                                                                                               ('Инерция. Масса',6,9,'HIGH','б',false,23,'DETAILED','','kirik7.pdf#page=23','Деревянный шар массой 1 кг поместили в широкий сосуд с водой. Шар плавает на поверхности воды. Изменилась ли масса шара?');
INSERT INTO tasks (title,task_number,self_task_number,task_level,task_letter,has_image,page_number,answer_type,answer,page_link,task_text) VALUES
                                                                                                                                               ('Плотность',1,10,'INITIAL',' ',false,24,'DETAILED','','kirik7.pdf#page=24','Выпишите из таблицы учебника значения плотности железа и мрамора. Плотность какого вещества больше?'),
                                                                                                                                               ('Плотность',2,10,'INITIAL',' ',false,24,'DETAILED','','kirik7.pdf#page=24','Выпишите из таблицы учебника значения плотности гранита и латуни. Плотность какого вещества меньше?'),
                                                                                                                                               ('Плотность',3,10,'INITIAL',' ',false,24,'DETAILED','','kirik7.pdf#page=24','Плотность железа 7,8 г/см³, а плотность алюминия 2700 кг/м³. Плотность какого вещества больше?'),
                                                                                                                                               ('Плотность',4,10,'INITIAL',' ',false,24,'DETAILED','','kirik7.pdf#page=24','Плотность бетона 2200 кг/м³, а плотность латуни 8,5 г/см³. Плотность какого вещества меньше?'),
                                                                                                                                               ('Плотность',5,10,'INITIAL',' ',false,24,'DETAILED','','kirik7.pdf#page=24','Посмотрите в таблице учебника плотности жидкостей и запишите, какова масса 1 м³ керосина.'),
                                                                                                                                               ('Плотность',6,10,'INITIAL',' ',false,24,'DETAILED','','kirik7.pdf#page=24','Посмотрите в таблице учебника плотности твердых тел и запишите, какова масса 1 см³ латуни.'),
                                                                                                                                               ('Плотность',1,10,'MIDDLE',' ',false,24,'DETAILED','','kirik7.pdf#page=24','Три кубика — из мрамора, льда и латуни — имеют одинаковый объем. Какой из них имеет наибольшую массу, какой — наименьшую?'),
                                                                                                                                               ('Плотность',2,10,'MIDDLE',' ',false,24,'SHORT','16 кг','kirik7.pdf#page=24','Какая масса керосина может быть влита в бидон емкостью 0,02 м³?'),
                                                                                                                                               ('Плотность',3,10,'MIDDLE',' ',false,24,'SHORT','из стали','kirik7.pdf#page=24','Из какого металла изготовлена деталь, если ее масса 3,9 кг, а объем 500 см³?'),
                                                                                                                                               ('Плотность',4,10,'MIDDLE',' ',false,24,'SHORT','150 м³','kirik7.pdf#page=24','Рыболовное судно, отправляясь на промысел, берет с собой 120 т нефти. Какой емкости должна быть цистерна?'),
                                                                                                                                               ('Плотность',5,10,'MIDDLE',' ',false,24,'SHORT','42,6 т','kirik7.pdf#page=24','Вместимость цистерны 60 м³. Сколько тонн бензина можно в нее налить?'),
                                                                                                                                               ('Плотность',6,10,'MIDDLE',' ',false,24,'SHORT','2700 кг/м³','kirik7.pdf#page=24','Мраморная плита имеет объем 0,02 м³. Найдите плотность мрамора, если масса плиты 54 кг.'),
                                                                                                                                               ('Плотность',7,10,'MIDDLE',' ',false,24,'SHORT','в 17 раз','kirik7.pdf#page=24','Во сколько раз объем, занимаемый ртутью, меньше объема нефти такой же массы?'),
                                                                                                                                               ('Плотность',8,10,'MIDDLE',' ',false,24,'DETAILED','','kirik7.pdf#page=24','Железный и алюминиевый стержень имеют одинаковые сечения и массу? Какой из стержней длиннее?'),
                                                                                                                                               ('Плотность',1,10,'SUFFICIENT','а',false,24,'SHORT','1200','kirik7.pdf#page=24','Сколько штук строительного кирпича размером 250 × 120 × 65 мм допускается перевозить на автомашине грузоподъемностью 4 т?'),
                                                                                                                                               ('Плотность',1,10,'SUFFICIENT','б',false,24,'DETAILED','','kirik7.pdf#page=24','Увеличивается ли плотность газов при охлаждении?'),
                                                                                                                                               ('Плотность',2,10,'SUFFICIENT','а',false,25,'SHORT','2,5 см','kirik7.pdf#page=25','Имеются два бруска одинаковой массы: серебряный и медный. Размеры серебряного — 2 × 5 × 6 см. Длина медного бруска 7 см, ширина 4 см. Какова его высота?'),
                                                                                                                                               ('Плотность',2,10,'SUFFICIENT','б',false,25,'DETAILED','','kirik7.pdf#page=25','Одинаковую ли массу имеют ведро с питьевой водой и такое же ведро, заполненное морской водой?'),
                                                                                                                                               ('Плотность',3,10,'SUFFICIENT','а',false,25,'SHORT','35','kirik7.pdf#page=25','Аквариум необходимо наполнить водой. Сколько ведер воды потребуется, если в ведро входит 10 кг воды, а размеры аквариума таковы: длина 1 м, ширина 0,5 м, а уровень воды в нем должен быть 70 см?'),
                                                                                                                                               ('Плотность',3,10,'SUFFICIENT','б',false,25,'DETAILED','','kirik7.pdf#page=25','Увеличивается или уменьшается плотность твердых тел при нагревании?'),
                                                                                                                                               ('Плотность',4,10,'SUFFICIENT','а',false,25,'SHORT','полый','kirik7.pdf#page=25','Медный шар имеет массу 840 г при объеме 120 см³. Сплошной этот шар или полый?'),
                                                                                                                                               ('Плотность',4,10,'SUFFICIENT','б',false,25,'DETAILED','','kirik7.pdf#page=25','Какая из трех ложек одинаковой массы — стальная, алюминиевая или серебряная — имеет большие размеры?'),
                                                                                                                                               ('Плотность',5,10,'SUFFICIENT','а',false,25,'SHORT','426 км','kirik7.pdf#page=25','Какой путь может проехать без заправки горючего автомобиль, если на 100 км пути его двигатель расходует 10 кг бензина, а вместимость топливного бака 60 л?'),
                                                                                                                                               ('Плотность',5,10,'SUFFICIENT','б',false,25,'DETAILED','','kirik7.pdf#page=25','Какая из трех ложек одинакового объема — стальная, алюминиевая или серебряная — имеют большую массу?'),
                                                                                                                                               ('Плотность',6,10,'SUFFICIENT','а',false,25,'SHORT','10 см³','kirik7.pdf#page=25','Определить объем полости пробки стеклянного графина, если при погружении в воду она вытесняет 50 г воды и имеет массу 100 г.'),
                                                                                                                                               ('Плотность',6,10,'SUFFICIENT','б',false,25,'DETAILED','','kirik7.pdf#page=25','Два одинаковых ящика наполнены дробью: в одном крупная, в другом мелкая. Какой из них имеет большую массу?'),
                                                                                                                                               ('Плотность',7,10,'SUFFICIENT','а',false,25,'SHORT','337,5 г','kirik7.pdf#page=25','Какую массу имеет куб с площадью поверхности 150 см², если плотность вещества, из которого он изготовлен, равна 2700 кг/м³?'),
                                                                                                                                               ('Плотность',7,10,'SUFFICIENT','б',false,25,'DETAILED','','kirik7.pdf#page=25','Чем объяснить отличие плотности водяного пара от плотности воды?'),
                                                                                                                                               ('Плотность',8,10,'SUFFICIENT','а',false,25,'SHORT','7700 кг/м³','kirik7.pdf#page=25','Пробирка, наполненная водой, имеет массу 44 г. Эта же пробирка, но с кусочком стали массой 10 г, доверху залитая водой, имеет массу 52,7 г. Определить плотность стали, помещенной в пробирку.'),
                                                                                                                                               ('Плотность',8,10,'SUFFICIENT','б',false,25,'DETAILED','','kirik7.pdf#page=25','Как определить массу стальной гайки, не взвешивая ее?'),
                                                                                                                                               ('Плотность',1,10,'HIGH',' ',false,25,'SHORT','0,7 см','kirik7.pdf#page=25','Полый алюминиевый куб ребром 10 см имеет массу 1 кг. Какова толщина стенок куба?'),
                                                                                                                                               ('Плотность',2,10,'HIGH',' ',false,25,'SHORT','2,4 г/см³','kirik7.pdf#page=25','Стакан, заполненный до краев водой, имеет массу 214,6 г. Когда в этот стакан с водой поместили небольшой камень массой 29,8 г и часть воды вылилась наружу, масса стакана с содержимым оказалась равной 232 г. Определить плотность вещества камня.'),
                                                                                                                                               ('Плотность',3,10,'HIGH',' ',false,25,'SHORT','226 г','kirik7.pdf#page=25','Кусок сплава из свинца и олова массой 664 г имеет плотность 8,3 г/см³. Определить массу свинца в сплаве. Принять объем сплава равным сумме объемов его составных частей.'),
                                                                                                                                               ('Плотность',4,10,'HIGH',' ',false,26,'SHORT','0,09 кг','kirik7.pdf#page=26','В чистой воде растворена кислота. Масса раствора 240 г, а его плотность 1,2 г/см³. Определите массу кислоты, содержащейся в растворе, если плотность кислоты 1,8 г/см³. Принять объем раствора равным сумме объемов его составных частей.'),
                                                                                                                                               ('Плотность',5,10,'HIGH',' ',false,26,'SHORT','19,5 г; 6,75 г','kirik7.pdf#page=26','Железная и алюминиевая детали имеют одинаковые объемы. Найдите массы этих деталей, если масса железной детали на 12,75 г больше массы алюминиевой.'),
                                                                                                                                               ('Плотность',6,10,'HIGH',' ',false,26,'SHORT','8100 кг/м³','kirik7.pdf#page=26','Сплав состоит из олова массой 2,92 кг и свинца массой 1,13 кг. Какова плотность сплава, если считать, что объем сплава равен сумме объемов его составных частей?'),
                                                                                                                                               ('Плотность',7,10,'HIGH',' ',false,26,'SHORT','77,5 г','kirik7.pdf#page=26','В куске кварца содержится небольшой самородок золота. Масса куска равна 100 г, его средняя плотность 8 г/см³. Определите массу золота, содержащегося в куске кварца, если плотность кварца 2,65 г/см³, а плотность золота 19,4 г/см³.'),
                                                                                                                                               ('Плотность',8,10,'HIGH',' ',false,26,'SHORT','3,5 г/см³','kirik7.pdf#page=26','В сосуд, заполненный водой, бросают кусок алюминиевого сплава. После того, как часть воды вылилась из сосуда, масса его с оставшейся водой и куском сплава увеличилась на 25 г. Когда вместо воды использовали жидкое масло плотностью 0,9 г/см³ и повторили измерения, то масса сосуда с маслом и куском сплава увеличилась на 26 г. Определите плотность сплава.');
